module isu_ctrl(
  input        clock,
               io_ex1_valid,
               io_ex2_valid,
               io_ex3_valid,
               io_ex4_valid,
               io_wb_valid,
               io_iss_rs1_ren,
  input  [4:0] io_iss_rs1_addr,
               io_iss_rs1_need,
  input        io_iss_rs2_ren,
  input  [4:0] io_iss_rs2_addr,
               io_iss_rs2_need,
  input        io_idu_rs1_ren,
  input  [4:0] io_idu_rs1_addr,
  input        io_idu_rs2_ren,
  input  [4:0] io_idu_rs2_addr,
  input        io_ex1_rd_wen,
  input  [4:0] io_ex1_rd_addr,
               io_ex1_rd_when,
  input        io_ex2_rd_wen,
  input  [4:0] io_ex2_rd_addr,
               io_ex2_rd_when,
  input        io_ex3_rd_wen,
  input  [4:0] io_ex3_rd_addr,
               io_ex3_rd_when,
  input        io_ex4_rd_wen,
  input  [4:0] io_ex4_rd_addr,
               io_ex4_rd_when,
  input        io_wb_rd_wen,
  input  [4:0] io_wb_rd_when,
  output [5:0] io_nxt_rs1_where_ex1,
               io_nxt_rs2_where_ex1,
               io_rs1_fwd_sel_iss,
               io_rs2_fwd_sel_iss,
  output [4:0] io_agu_fwd_sel_iss,
  input        io_raw_long_valid_iss,
               io_long_stall_wb,
               io_backend_stall,
               io_long_in_flight,
  output       io_interlock
);

  reg  [3:0] early_addr_cmp_agu_iss;
  reg  [3:0] early_addr_cmp_iss_rs1;
  reg  [3:0] early_addr_cmp_iss_rs2;
  wire       _rs1_where_iss_T = io_iss_rs1_ren & io_ex1_rd_wen;
  wire       _rs1_where_iss_T_3 = io_ex1_rd_addr == io_iss_rs1_addr;
  wire       _rs2_where_iss_T = io_iss_rs2_ren & io_ex1_rd_wen;
  wire       _rs2_where_iss_T_3 = io_ex1_rd_addr == io_iss_rs2_addr;
  wire       _ready_mask_T_3 = ~(io_ex1_rd_when[0]) & io_ex1_valid & io_ex1_rd_wen;
  wire       _ready_mask_T_7 = ~(io_ex2_rd_when[1]) & io_ex2_valid & io_ex2_rd_wen;
  wire       _ready_mask_T_11 = ~(io_ex3_rd_when[2]) & io_ex3_valid & io_ex3_rd_wen;
  wire       _ready_mask_T_15 = ~(io_ex4_rd_when[3]) & io_ex4_valid & io_ex4_rd_wen;
  wire       _ready_mask_T_16 = io_wb_valid & io_wb_rd_wen;
  wire [4:0] cannot_fwd_from_ex1 = {io_ex1_rd_when[3:0], 1'h1};
  wire [4:0] cannot_fwd_from_ex2 = {1'h0, io_ex2_rd_when[3:0]};
  wire [4:0] cannot_fwd_from_ex3 = {2'h0, io_ex3_rd_when[3:1]};
  wire [4:0] cannot_fwd_from_ex4 = {3'h0, io_ex4_rd_when[3:2]};
  wire [4:0] cannot_fwd_from_wb = {4'h0, io_wb_rd_when[4] | io_long_stall_wb};
  wire       _rs1_where_iss_T_5 =
    _rs1_where_iss_T & (|io_ex1_rd_addr) & _rs1_where_iss_T_3 & io_ex1_valid;
  wire       _rs2_where_iss_T_5 =
    _rs2_where_iss_T & (|io_ex1_rd_addr) & _rs2_where_iss_T_3 & io_ex1_valid;
  wire [1:0] _GEN = {_ready_mask_T_3, _ready_mask_T_7};
  wire [2:0] _GEN_0 = {_ready_mask_T_3, _ready_mask_T_7, _ready_mask_T_11};
  wire [3:0] _GEN_1 =
    {_ready_mask_T_3, _ready_mask_T_7, _ready_mask_T_11, _ready_mask_T_15};
  wire [5:0] _GEN_2 =
    {io_raw_long_valid_iss & (io_long_in_flight | io_long_stall_wb),
     io_iss_rs1_need
       & ({5{_rs1_where_iss_T_5}} & cannot_fwd_from_ex1 | {5{early_addr_cmp_iss_rs1[3]}}
          & cannot_fwd_from_ex2 | {5{early_addr_cmp_iss_rs1[2]}} & cannot_fwd_from_ex3
          | {5{early_addr_cmp_iss_rs1[1]}} & cannot_fwd_from_ex4
          | {5{early_addr_cmp_iss_rs1[0]}} & cannot_fwd_from_wb) | io_iss_rs2_need
       & ({5{_rs2_where_iss_T_5}} & cannot_fwd_from_ex1 | {5{early_addr_cmp_iss_rs2[3]}}
          & cannot_fwd_from_ex2 | {5{early_addr_cmp_iss_rs2[2]}} & cannot_fwd_from_ex3
          | {5{early_addr_cmp_iss_rs2[1]}} & cannot_fwd_from_ex4
          | {5{early_addr_cmp_iss_rs2[0]}} & cannot_fwd_from_wb)};
  wire [3:0] _early_addr_cmp_iss_rs1_T =
    (|_GEN_2)
      ? {_rs1_where_iss_T & (|io_ex1_rd_addr) & _rs1_where_iss_T_3 & io_ex1_valid,
         io_iss_rs1_ren & io_ex2_rd_wen & (|io_ex2_rd_addr)
           & io_ex2_rd_addr == io_iss_rs1_addr & io_ex2_valid,
         io_iss_rs1_ren & io_ex3_rd_wen & (|io_ex3_rd_addr)
           & io_ex3_rd_addr == io_iss_rs1_addr & io_ex3_valid,
         io_iss_rs1_ren & io_ex4_rd_wen & (|io_ex4_rd_addr)
           & io_ex4_rd_addr == io_iss_rs1_addr & io_ex4_valid}
      : {io_idu_rs1_ren & io_ex1_rd_wen & (|io_ex1_rd_addr)
           & io_ex1_rd_addr == io_idu_rs1_addr & io_ex1_valid,
         io_idu_rs1_ren & io_ex2_rd_wen & (|io_ex2_rd_addr)
           & io_ex2_rd_addr == io_idu_rs1_addr & io_ex2_valid,
         io_idu_rs1_ren & io_ex3_rd_wen & (|io_ex3_rd_addr)
           & io_ex3_rd_addr == io_idu_rs1_addr & io_ex3_valid,
         io_idu_rs1_ren & io_ex4_rd_wen & (|io_ex4_rd_addr)
           & io_ex4_rd_addr == io_idu_rs1_addr & io_ex4_valid};
  always @(posedge clock) begin
    if (~(io_long_stall_wb | io_backend_stall)) begin
      early_addr_cmp_agu_iss <= _early_addr_cmp_iss_rs1_T;
      early_addr_cmp_iss_rs1 <= _early_addr_cmp_iss_rs1_T;
      early_addr_cmp_iss_rs2 <=
        (|_GEN_2)
          ? {_rs2_where_iss_T & (|io_ex1_rd_addr) & _rs2_where_iss_T_3 & io_ex1_valid,
             io_iss_rs2_ren & io_ex2_rd_wen & (|io_ex2_rd_addr)
               & io_ex2_rd_addr == io_iss_rs2_addr & io_ex2_valid,
             io_iss_rs2_ren & io_ex3_rd_wen & (|io_ex3_rd_addr)
               & io_ex3_rd_addr == io_iss_rs2_addr & io_ex3_valid,
             io_iss_rs2_ren & io_ex4_rd_wen & (|io_ex4_rd_addr)
               & io_ex4_rd_addr == io_iss_rs2_addr & io_ex4_valid}
          : {io_idu_rs2_ren & io_ex1_rd_wen & (|io_ex1_rd_addr)
               & io_ex1_rd_addr == io_idu_rs2_addr & io_ex1_valid,
             io_idu_rs2_ren & io_ex2_rd_wen & (|io_ex2_rd_addr)
               & io_ex2_rd_addr == io_idu_rs2_addr & io_ex2_valid,
             io_idu_rs2_ren & io_ex3_rd_wen & (|io_ex3_rd_addr)
               & io_ex3_rd_addr == io_idu_rs2_addr & io_ex3_valid,
             io_idu_rs2_ren & io_ex4_rd_wen & (|io_ex4_rd_addr)
               & io_ex4_rd_addr == io_idu_rs2_addr & io_ex4_valid};
    end
  end // always @(posedge)
  assign io_nxt_rs1_where_ex1 =
    {2'h0,
     _rs1_where_iss_T_5 & ~(_rs1_where_iss_T_5 & _ready_mask_T_3),
     early_addr_cmp_iss_rs1[3]
       & ({_rs1_where_iss_T_5, early_addr_cmp_iss_rs1[3]} & _GEN) == 2'h0,
     early_addr_cmp_iss_rs1[2]
       & ({_rs1_where_iss_T_5, early_addr_cmp_iss_rs1[3:2]} & _GEN_0) == 3'h0,
     early_addr_cmp_iss_rs1[1]
       & ({_rs1_where_iss_T_5, early_addr_cmp_iss_rs1[3:1]} & _GEN_1) == 4'h0};
  assign io_nxt_rs2_where_ex1 =
    {2'h0,
     _rs2_where_iss_T_5 & ~(_rs2_where_iss_T_5 & _ready_mask_T_3),
     early_addr_cmp_iss_rs2[3]
       & ({_rs2_where_iss_T_5, early_addr_cmp_iss_rs2[3]} & _GEN) == 2'h0,
     early_addr_cmp_iss_rs2[2]
       & ({_rs2_where_iss_T_5, early_addr_cmp_iss_rs2[3:2]} & _GEN_0) == 3'h0,
     early_addr_cmp_iss_rs2[1]
       & ({_rs2_where_iss_T_5, early_addr_cmp_iss_rs2[3:1]} & _GEN_1) == 4'h0};
  assign io_rs1_fwd_sel_iss =
    _rs1_where_iss_T_5 & _ready_mask_T_3
      ? 6'h2
      : early_addr_cmp_iss_rs1[3] & _ready_mask_T_7
          ? 6'h4
          : early_addr_cmp_iss_rs1[2] & _ready_mask_T_11
              ? 6'h8
              : early_addr_cmp_iss_rs1[1] & _ready_mask_T_15
                  ? 6'h10
                  : early_addr_cmp_iss_rs1[0] & _ready_mask_T_16 ? 6'h20 : 6'h1;
  assign io_rs2_fwd_sel_iss =
    _rs2_where_iss_T_5 & _ready_mask_T_3
      ? 6'h2
      : early_addr_cmp_iss_rs2[3] & _ready_mask_T_7
          ? 6'h4
          : early_addr_cmp_iss_rs2[2] & _ready_mask_T_11
              ? 6'h8
              : early_addr_cmp_iss_rs2[1] & _ready_mask_T_15
                  ? 6'h10
                  : early_addr_cmp_iss_rs2[0] & _ready_mask_T_16 ? 6'h20 : 6'h1;
  assign io_agu_fwd_sel_iss =
    early_addr_cmp_agu_iss[3]
      ? 5'h10
      : early_addr_cmp_agu_iss[2]
          ? 5'h8
          : early_addr_cmp_agu_iss[1] ? 5'h4 : early_addr_cmp_agu_iss[0] ? 5'h2 : 5'h1;
  assign io_interlock = |_GEN_2;
endmodule

module isu_rf(
  input  [31:0] io_gpr_rs1_val,
                io_gpr_rs2_val,
                io_ex1_reg_val,
                io_ex2_reg_val,
                io_ex3_reg_val,
                io_ex4_reg_val,
                io_wb_reg_val,
  input  [5:0]  io_rs1_fwd_sel_iss,
                io_rs2_fwd_sel_iss,
  output [31:0] io_rs1_val,
                io_rs2_val
);

  assign io_rs1_val =
    {32{io_rs1_fwd_sel_iss[0]}} & io_gpr_rs1_val | {32{io_rs1_fwd_sel_iss[1]}}
    & io_ex1_reg_val | {32{io_rs1_fwd_sel_iss[2]}} & io_ex2_reg_val
    | {32{io_rs1_fwd_sel_iss[3]}} & io_ex3_reg_val | {32{io_rs1_fwd_sel_iss[4]}}
    & io_ex4_reg_val | {32{io_rs1_fwd_sel_iss[5]}} & io_wb_reg_val;
  assign io_rs2_val =
    {32{io_rs2_fwd_sel_iss[0]}} & io_gpr_rs2_val | {32{io_rs2_fwd_sel_iss[1]}}
    & io_ex1_reg_val | {32{io_rs2_fwd_sel_iss[2]}} & io_ex2_reg_val
    | {32{io_rs2_fwd_sel_iss[3]}} & io_ex3_reg_val | {32{io_rs2_fwd_sel_iss[4]}}
    & io_ex4_reg_val | {32{io_rs2_fwd_sel_iss[5]}} & io_wb_reg_val;
endmodule

module isu_agu(
  input  [4:0]  io_agu_fwd_sel_iss,
  input  [31:0] io_gpr_rs1_val,
                io_ex1_reg_val_q,
                io_ex2_reg_val_q,
                io_ex3_reg_val_q,
