  assign io_base =
    {32{io_agu_fwd_sel_iss[4]}} & io_ex1_reg_val_q | {32{io_agu_fwd_sel_iss[3]}}
    & io_ex2_reg_val_q | {32{io_agu_fwd_sel_iss[2]}} & io_ex3_reg_val_q
    | {32{io_agu_fwd_sel_iss[1]}} & io_ex4_reg_val_q | {32{io_agu_fwd_sel_iss[0]}}
    & io_gpr_rs1_val;
endmodule

