    .io_ex3_valid          (io_ex3_valid),
    .io_ex4_valid          (io_ex4_valid),
    .io_wb_valid           (io_wb_valid),
    .io_iss_rs1_ren        (io_in_bits_ALU_operand1 == 6'h4),
    .io_iss_rs1_addr       (io_in_bits_rs1_addr),
    .io_iss_rs1_need
      (io_in_valid & io_in_bits_mem_bytes != 2'h3 ? 5'h1F : io_in_bits_rs1_need),
    .io_iss_rs2_ren        (io_in_bits_ALU_operand2 == 6'h8),
    .io_iss_rs2_addr       (io_in_bits_rs2_addr),
    .io_iss_rs2_need       (io_in_bits_rs2_need),
    .io_idu_rs1_ren        (io_idu_rs1_ren),
    .io_idu_rs1_addr       (io_idu_rs1_addr),
    .io_idu_rs2_ren        (io_idu_rs2_ren),
    .io_idu_rs2_addr       (io_idu_rs2_addr),
    .io_ex1_rd_wen         (io_ex1_rd_wen),
    .io_ex1_rd_addr        (io_ex1_rd_addr),
    .io_ex1_rd_when        (io_ex1_rd_when),
    .io_ex2_rd_wen         (io_ex2_rd_wen),
    .io_ex2_rd_addr        (io_ex2_rd_addr),
    .io_ex2_rd_when        (io_ex2_rd_when),
    .io_ex3_rd_wen         (io_ex3_rd_wen),
    .io_ex3_rd_addr        (io_ex3_rd_addr),
    .io_ex3_rd_when        (io_ex3_rd_when),
    .io_ex4_rd_wen         (io_ex4_rd_wen),
    .io_ex4_rd_addr        (io_ex4_rd_addr),
    .io_ex4_rd_when        (io_ex4_rd_when),
    .io_wb_rd_wen          (io_wb_rd_wen),
    .io_wb_rd_when         (io_wb_rd_when),
    .io_nxt_rs1_where_ex1  (io_out_bits_rs1_where_ex1),
    .io_nxt_rs2_where_ex1  (io_out_bits_rs2_where_ex1),
    .io_rs1_fwd_sel_iss    (_isu_ctrl_io_rs1_fwd_sel_iss),
    .io_rs2_fwd_sel_iss    (_isu_ctrl_io_rs2_fwd_sel_iss),
    .io_agu_fwd_sel_iss    (_isu_ctrl_io_agu_fwd_sel_iss),
    .io_raw_long_valid_iss
      (io_in_valid & (io_in_bits_mdu_ctrl[1:0] == 2'h2 | io_in_bits_bit_ctrl == 4'h7)),
    .io_long_stall_wb      (io_long_stall_wb),
    .io_backend_stall      (io_backend_stall),
    .io_long_in_flight     (io_long_in_flight),
    .io_interlock          (_isu_ctrl_io_interlock)
  );
  isu_rf isu_rf (
    .io_gpr_rs1_val     (io_gpr_rs1_val),
    .io_gpr_rs2_val     (io_gpr_rs2_val),
    .io_ex1_reg_val     (io_ex1_reg_val),
    .io_ex2_reg_val     (io_ex2_reg_val),
    .io_ex3_reg_val     (io_ex3_reg_val),
    .io_ex4_reg_val     (io_ex4_reg_val),
    .io_wb_reg_val      (io_wb_reg_val),
    .io_rs1_fwd_sel_iss (_isu_ctrl_io_rs1_fwd_sel_iss),
    .io_rs2_fwd_sel_iss (_isu_ctrl_io_rs2_fwd_sel_iss),
    .io_rs1_val         (_isu_rf_io_rs1_val),
    .io_rs2_val         (_isu_rf_io_rs2_val)
  );
  isu_agu isu_agu (
    .io_agu_fwd_sel_iss (_isu_ctrl_io_agu_fwd_sel_iss),
