    .io_ex1_reg_val_q   (io_ex1_reg_val_q),
    .io_ex2_reg_val_q   (io_ex2_reg_val_q),
    .io_ex3_reg_val_q   (io_ex3_reg_val_q),
    .io_ex4_reg_val_q   (io_ex4_reg_val_q),
    .io_base            (_isu_agu_io_base)
  );
  assign io_in_ready = io_out_ready;
  assign io_out_valid = io_in_valid & ~_isu_ctrl_io_interlock;
  assign io_out_bits_predicted_pc = io_in_bits_predicted_pc;
  assign io_out_bits_alu_ctrl = io_in_bits_alu_ctrl;
  assign io_out_bits_bru_ctrl = io_in_bits_bru_ctrl;
  assign io_out_bits_mdu_ctrl = io_in_bits_mdu_ctrl;
  assign io_out_bits_bit_ctrl = io_in_bits_bit_ctrl;
  assign io_out_bits_csr_ctrl = io_in_bits_csr_ctrl;
  assign io_out_bits_csr_mask = io_in_bits_csr_mask;
  assign io_out_bits_jump = io_in_bits_jump;
  assign io_out_bits_ras_push = io_in_bits_ras_push;
  assign io_out_bits_ras_pop = io_in_bits_ras_pop;
  assign io_out_bits_snpc = io_in_bits_snpc;
  assign io_out_bits_imm = io_in_bits_imm;
  assign io_out_bits_alu_din1 =
    {32{io_in_bits_ALU_operand1[1]}} & io_in_bits_imm | {32{io_in_bits_ALU_operand1[5]}}
    & io_in_bits_snpc | {32{io_in_bits_ALU_operand1[2]}} & _isu_rf_io_rs1_val;
  assign io_out_bits_alu_din2 =
    {32{io_in_bits_ALU_operand2[1]}} & io_in_bits_imm | {32{io_in_bits_ALU_operand2[5]}}
    & io_in_bits_snpc | {32{io_in_bits_ALU_operand2[4]}} & io_in_bits_pc
    | {32{io_in_bits_ALU_operand2[3]}} & _isu_rf_io_rs2_val;
  assign io_out_bits_rs1_val = _isu_rf_io_rs1_val;
  assign io_out_bits_rs2_val = _isu_rf_io_rs2_val;
  assign io_out_bits_rs1_need = io_in_bits_rs1_need;
  assign io_out_bits_rs2_need = io_in_bits_rs2_need;
  assign io_out_bits_when = io_in_bits_when;
  assign io_out_bits_pc = io_in_bits_pc;
