module ALU(
  input  [11:0] io_alu_ctrl,
  input  [31:0] io_din1,
                io_din2,
  output [31:0] io_dout
);

  wire [62:0] _dout_T_37 = {31'h0, io_din1} << io_din2[4:0];
  wire [31:0] _GEN = {27'h0, io_din2[4:0]};
  wire [31:0] _dout_T_54 =
    {32{io_alu_ctrl[0]}} & io_din1 | {32{io_alu_ctrl[1]}} & io_din2 | {32{io_alu_ctrl[2]}}
    & io_din1 + io_din2 | {32{io_alu_ctrl[3]}} & io_din1 - io_din2 | {32{io_alu_ctrl[4]}}
    & (io_din1 ^ io_din2) | {32{io_alu_ctrl[5]}} & (io_din1 | io_din2)
    | {32{io_alu_ctrl[6]}} & io_din1 & io_din2 | {32{io_alu_ctrl[7]}} & _dout_T_37[31:0]
    | {32{io_alu_ctrl[8]}} & io_din1 >> _GEN | {32{io_alu_ctrl[9]}}
    & $signed($signed(io_din1) >>> _GEN);
  assign io_dout =
    {_dout_T_54[31:1],
     _dout_T_54[0] | io_alu_ctrl[10] & $signed(io_din1) < $signed(io_din2)
       | io_alu_ctrl[11] & io_din1 < io_din2};
endmodule

module BRU(
  input  [8:0]  io_bru_ctrl,
  input  [31:0] io_imm,
                io_snpc,
                io_pc,
                io_rs1_val,
                io_rs2_val,
  output        io_redirect,
  output [31:0] io_target_pc
);

  wire _redirect_T = io_bru_ctrl[2:0] == 3'h1;
  wire _redirect_T_2 = io_bru_ctrl[2:0] == 3'h2;
  wire _redirect_T_4 = io_bru_ctrl[2:0] == 3'h4;
  assign io_redirect =
    _redirect_T_4 | _redirect_T_2 | _redirect_T
    & (io_bru_ctrl[8:3] == 6'h20
         ? io_rs1_val >= io_rs2_val
         : io_bru_ctrl[8:3] == 6'h8
             ? io_rs1_val < io_rs2_val
             : io_bru_ctrl[8:3] == 6'h10
                 ? $signed(io_rs1_val) >= $signed(io_rs2_val)
                 : io_bru_ctrl[8:3] == 6'h4
                     ? $signed(io_rs1_val) < $signed(io_rs2_val)
                     : io_bru_ctrl[8:3] == 6'h2
                         ? io_rs1_val != io_rs2_val
                         : io_bru_ctrl[8:3] == 6'h1 & io_rs1_val == io_rs2_val);
  assign io_target_pc =
    _redirect_T_4
      ? io_imm + io_rs1_val & 32'hFFFFFFFE
      : _redirect_T_2 | _redirect_T ? io_imm + io_pc : io_snpc;
endmodule

// external module Multiplier

module MUL(
  input         clock,
  input  [4:0]  io_mdu_ctrl,
  input         io_enable,
  input  [31:0] io_din1,
                io_din2,
  output [63:0] io_dout
);

  Multiplier Mult (
    .CLK (clock),
    .CE  (io_enable),
    .A   ({io_mdu_ctrl[4] & io_din1[31], io_din1}),
    .B   ({io_mdu_ctrl[3] & io_din2[31], io_din2}),
    .P   (io_dout)
  );
endmodule

// external module Divider

module DIV(
  input         clock,
                reset,
  input  [4:0]  io_mdu_ctrl,
  input         io_valid,
  input  [31:0] io_din1,
                io_din2,
  output [31:0] io_dout,
  output        io_stall,
                io_busy,
                io_done
);

  wire [63:0] _Div_m_axis_dout_tdata;
  reg  [5:0]  div_counter;
  reg         div_done_reg;
  wire        div_running = (|div_counter) & div_counter != 6'h23;
  reg         div_pos_reg;
  reg         div_by_zero_reg;
  reg  [31:0] div_dividend_reg;
  reg         div_quotient_neg_reg;
  reg         div_remainder_neg_reg;
  reg  [31:0] div_result_reg;
  wire        div_request = io_valid & io_mdu_ctrl[1:0] == 2'h2;
  wire        div_start = div_request & ~(|div_counter);
  wire        div_terminal = div_counter == 6'h23;
  always @(posedge clock) begin
    if (reset) begin
      div_counter <= 6'h0;
      div_done_reg <= 1'h0;
    end
    else begin
      if (div_start)
        div_counter <= 6'h1;
      else if (div_running)
        div_counter <= div_counter + 6'h1;
      else if (div_terminal)
        div_counter <= 6'h0;
      div_done_reg <= div_terminal;
    end
    if (div_start) begin
      div_pos_reg <= io_mdu_ctrl[2];
      div_by_zero_reg <= ~(|io_din2);
      div_dividend_reg <= io_din1;
      div_quotient_neg_reg <=
        (&(io_mdu_ctrl[4:3])) & (io_din1[31] ^ io_din2[31]) & (|io_din2);
      div_remainder_neg_reg <= (&(io_mdu_ctrl[4:3])) & io_din1[31];
    end
    if (div_terminal)
      div_result_reg <=
        div_by_zero_reg
          ? (div_pos_reg ? 32'hFFFFFFFF : div_dividend_reg)
          : div_pos_reg
              ? (div_quotient_neg_reg
                   ? 32'h0 - _Div_m_axis_dout_tdata[63:32]
                   : _Div_m_axis_dout_tdata[63:32])
              : div_remainder_neg_reg
                  ? 32'h0 - _Div_m_axis_dout_tdata[31:0]
                  : _Div_m_axis_dout_tdata[31:0];
  end // always @(posedge)
  Divider Div (
    .aclk                   (clock),
    .s_axis_dividend_tdata
      ((&(io_mdu_ctrl[4:3])) & io_din1[31] ? 32'h0 - io_din1 : io_din1),
    .s_axis_dividend_tready (/* unused */),
    .s_axis_dividend_tvalid (div_start & (|io_din2)),
    .s_axis_divisor_tdata
      ((&(io_mdu_ctrl[4:3])) & io_din2[31] ? 32'h0 - io_din2 : io_din2),
    .s_axis_divisor_tready  (/* unused */),
    .s_axis_divisor_tvalid  (div_start & (|io_din2)),
    .m_axis_dout_tdata      (_Div_m_axis_dout_tdata),
    .m_axis_dout_tvalid     (/* unused */)
  );
  assign io_dout = div_result_reg;
  assign io_stall = div_request & div_running;
  assign io_busy = |div_counter;
  assign io_done = div_done_reg;
endmodule

module CRC8Ex1(
  input  [31:0] io_rs1,
                io_rs2,
  output [31:0] io_bit_data,
                io_bit_aux
);

  wire        io_bit_aux_x16 = io_rs1[0] ^ io_rs2[0];
  wire [14:0] io_bit_aux_cx = {1'h0, {14{io_bit_aux_x16}} & 14'h2001} ^ io_rs2[15:1];
  wire        io_bit_aux_x16_1 = io_rs1[1] ^ io_bit_aux_cx[0];
  wire [14:0] io_bit_aux_cx_1 =
    {1'h0, {14{io_bit_aux_x16_1}} & 14'h2001} ^ {io_bit_aux_x16, io_bit_aux_cx[14:1]};
  wire        io_bit_aux_x16_2 = io_rs1[2] ^ io_bit_aux_cx_1[0];
  wire [14:0] io_bit_aux_cx_2 =
    {1'h0, {14{io_bit_aux_x16_2}} & 14'h2001} ^ {io_bit_aux_x16_1, io_bit_aux_cx_1[14:1]};
  wire        io_bit_aux_x16_3 = io_rs1[3] ^ io_bit_aux_cx_2[0];
  assign io_bit_data = io_rs1;
  assign io_bit_aux =
    {16'h0,
     io_bit_aux_x16_3,
     {1'h0, {14{io_bit_aux_x16_3}} & 14'h2001}
       ^ {io_bit_aux_x16_2, io_bit_aux_cx_2[14:1]}};
endmodule

module CSR(
  input         clock,
                reset,
                io_valid,
  input  [2:0]  io_ctrl,
  input  [31:0] io_wdata,
  input  [5:0]  io_mask,
  input         io_ecall,
                io_mret,
  input  [31:0] io_trap_pc,
  output [31:0] io_rdata,
                io_mtvec,
                io_mepc
);

  reg  [31:0] csrRegs_0_2;
  reg  [31:0] csrRegs_1_2;
  reg  [31:0] csrRegs_2_2;
  reg  [31:0] csrRegs_3_2;
  wire        _old_data_T = io_mask == 6'h1;
  wire        _old_data_T_2 = io_mask == 6'h2;
  wire        _old_data_T_4 = io_mask == 6'h4;
  wire        _old_data_T_6 = io_mask == 6'h8;
  wire [31:0] io_rdata_0 =
    _old_data_T_6
      ? csrRegs_3_2
      : _old_data_T_4
          ? csrRegs_2_2
          : _old_data_T_2 ? csrRegs_1_2 : _old_data_T ? csrRegs_0_2 : 32'h0;
  wire [31:0] csr_wdata =
    io_ctrl == 3'h3
      ? io_rdata_0 & ~io_wdata
      : {32{io_ctrl == 3'h2}} & io_rdata_0 | io_wdata;
  wire        do_write = io_valid & (|io_ctrl) & (|io_mask);
  always @(posedge clock) begin
    if (reset) begin
      csrRegs_0_2 <= 32'h1800;
      csrRegs_1_2 <= 32'h0;
      csrRegs_2_2 <= 32'h0;
      csrRegs_3_2 <= 32'h0;
    end
    else begin
      if (io_ecall) begin
        csrRegs_0_2 <=
          {csrRegs_0_2[31:8], csrRegs_0_2[3], csrRegs_0_2[6:4], 1'h0, csrRegs_0_2[2:0]};
        csrRegs_1_2 <= io_trap_pc;
        csrRegs_3_2 <= 32'hB;
      end
      else begin
        if (io_mret)
          csrRegs_0_2 <=
            {csrRegs_0_2[31:8], 1'h1, csrRegs_0_2[6:4], csrRegs_0_2[7], csrRegs_0_2[2:0]};
        else if (do_write & _old_data_T)
          csrRegs_0_2 <= csr_wdata;
        if (io_mret | ~(do_write & _old_data_T_2)) begin
        end
        else
          csrRegs_1_2 <= csr_wdata;
        if (io_mret | ~(do_write & _old_data_T_6)) begin
        end
        else
          csrRegs_3_2 <= csr_wdata;
      end
      if (io_ecall | io_mret | ~(do_write & _old_data_T_4)) begin
      end
      else
        csrRegs_2_2 <= csr_wdata;
    end
  end // always @(posedge)
  assign io_rdata = io_rdata_0;
  assign io_mtvec = csrRegs_2_2;
  assign io_mepc = csrRegs_1_2;
endmodule

module exu_ex1(
  input         clock,
                reset,
  output        io_in_ready,
  input         io_in_valid,
  input  [31:0] io_in_bits_predicted_pc,
  input  [11:0] io_in_bits_alu_ctrl,
  input  [8:0]  io_in_bits_bru_ctrl,
  input  [4:0]  io_in_bits_mdu_ctrl,
  input  [3:0]  io_in_bits_bit_ctrl,
  input  [2:0]  io_in_bits_csr_ctrl,
  input  [5:0]  io_in_bits_csr_mask,
  input         io_in_bits_jump,
                io_in_bits_ras_push,
                io_in_bits_ras_pop,
  input  [31:0] io_in_bits_snpc,
                io_in_bits_imm,
                io_in_bits_alu_din1,
                io_in_bits_alu_din2,
                io_in_bits_rs1_val,
                io_in_bits_rs2_val,
  input  [4:0]  io_in_bits_when,
  input  [31:0] io_in_bits_pc,
  input  [4:0]  io_in_bits_rd_addr,
  input         io_in_bits_rd_wen,
  input  [31:0] io_in_bits_addr,
  input         io_in_bits_L_sign,
                io_in_bits_mem_wen,
  input  [1:0]  io_in_bits_mem_bytes,
  input  [2:0]  io_in_bits_envir,
  input         io_out_ready,
  output        io_out_valid,
  output [31:0] io_out_bits_pc,
                io_out_bits_pc_next,
                io_out_bits_addr,
                io_out_bits_mem_wdata,
  output        io_out_bits_mem_wen,
  output [31:0] io_out_bits_reg_data,
  output [4:0]  io_out_bits_mdu_ctrl,
  output [3:0]  io_out_bits_bit_ctrl,
  output [31:0] io_out_bits_bit_data,
                io_out_bits_bit_aux,
  output        io_out_bits_L_sign,
  output [1:0]  io_out_bits_mem_bytes,
  output [4:0]  io_out_bits_rd_addr,
  output        io_out_bits_rd_wen,
                io_out_bits_is_load,
  output [2:0]  io_out_bits_envir,
  output [4:0]  io_out_bits_when,
  input         io_flush,
  output [63:0] io_mul_out,
  output [31:0] io_div_out,
  output        io_div_busy,
                io_div_done,
                io_bpu_update_en,
  output [31:0] io_bpu_update_pc,
  output        io_bpu_update_ras_push,
                io_bpu_update_ras_pop,
  output [31:0] io_bpu_update_ras_addr,
                io_branch_resolve_actual_pc,
  output        io_branch_resolve_actual_taken,
                io_branch_resolve_mispredict,
  output [31:0] io_reg_val,
  output        io_rd_wen,
  output [4:0]  io_rd_addr,
                io_rd_when
);

  wire [31:0] _CSR_io_rdata;
  wire [31:0] _CSR_io_mtvec;
  wire [31:0] _CSR_io_mepc;
  wire [31:0] _CRC8_EX1_io_bit_data;
  wire [31:0] _CRC8_EX1_io_bit_aux;
  wire        _DIV_io_stall;
  wire        _BRU_io_redirect;
  wire [31:0] _BRU_io_target_pc;
  wire [31:0] _ALU_io_dout;
  wire        valid = io_in_valid & ~io_flush;
  wire        isCrc8 = io_in_bits_bit_ctrl == 4'h9;
  wire        io_out_valid_0 = valid & ~_DIV_io_stall;
  wire        exu_fire = io_out_valid_0 & io_out_ready;
  wire        is_ecall = io_in_bits_envir == 3'h1;
  wire        is_mret = io_in_bits_envir == 3'h3;
  wire        trap_redirect = exu_fire & (is_ecall | is_mret);
  wire [31:0] trap_target_pc =
    {32{is_ecall}} & _CSR_io_mtvec | {32{is_mret}} & _CSR_io_mepc;
  wire [31:0] actual_pc =
    _BRU_io_redirect
      ? _BRU_io_target_pc
      : trap_redirect ? trap_target_pc : io_in_bits_snpc;
  wire [31:0] reg_val =
    io_in_bits_bit_ctrl == 4'h4 | io_in_bits_bit_ctrl == 4'h8
      ? 32'h0
      : (|io_in_bits_csr_ctrl) ? _CSR_io_rdata : _ALU_io_dout;
  ALU ALU (
    .io_alu_ctrl (io_in_bits_alu_ctrl),
    .io_din1     (io_in_bits_alu_din1),
    .io_din2     (io_in_bits_alu_din2),
    .io_dout     (_ALU_io_dout)
  );
  BRU BRU (
    .io_bru_ctrl  (io_in_bits_bru_ctrl),
    .io_imm       (io_in_bits_imm),
    .io_snpc      (io_in_bits_snpc),
    .io_pc        (io_in_bits_pc),
    .io_rs1_val   (io_in_bits_rs1_val),
    .io_rs2_val   (io_in_bits_rs2_val),
    .io_redirect  (_BRU_io_redirect),
    .io_target_pc (_BRU_io_target_pc)
  );
  MUL MUL (
    .clock       (clock),
    .io_mdu_ctrl (io_in_bits_mdu_ctrl),
    .io_enable   (io_out_ready),
    .io_din1     (io_in_bits_rs1_val),
    .io_din2     (io_in_bits_rs2_val),
    .io_dout     (io_mul_out)
  );
  DIV DIV (
    .clock       (clock),
    .reset       (reset),
    .io_mdu_ctrl (io_in_bits_mdu_ctrl),
    .io_valid    (valid),
    .io_din1     (io_in_bits_rs1_val),
    .io_din2     (io_in_bits_rs2_val),
    .io_dout     (io_div_out),
    .io_stall    (_DIV_io_stall),
    .io_busy     (io_div_busy),
    .io_done     (io_div_done)
  );
  CRC8Ex1 CRC8_EX1 (
    .io_rs1      (io_in_bits_rs1_val),
    .io_rs2      (io_in_bits_rs2_val),
    .io_bit_data (_CRC8_EX1_io_bit_data),
    .io_bit_aux  (_CRC8_EX1_io_bit_aux)
  );
  CSR CSR (
    .clock      (clock),
    .reset      (reset),
    .io_valid   (exu_fire),
    .io_ctrl    ({1'h0, io_in_bits_csr_ctrl[1:0]}),
    .io_wdata   (io_in_bits_csr_ctrl[2] ? io_in_bits_imm : io_in_bits_rs1_val),
    .io_mask    (io_in_bits_csr_mask),
    .io_ecall   (exu_fire & is_ecall),
    .io_mret    (exu_fire & is_mret),
    .io_trap_pc (io_in_bits_pc),
    .io_rdata   (_CSR_io_rdata),
    .io_mtvec   (_CSR_io_mtvec),
    .io_mepc    (_CSR_io_mepc)
  );
  assign io_in_ready = io_out_ready & ~_DIV_io_stall;
  assign io_out_valid = io_out_valid_0;
  assign io_out_bits_pc = io_in_bits_pc;
  assign io_out_bits_pc_next = actual_pc;
  assign io_out_bits_addr = io_in_bits_addr;
  assign io_out_bits_mem_wdata = io_in_bits_rs2_val;
  assign io_out_bits_mem_wen = io_in_bits_mem_wen;
  assign io_out_bits_reg_data = reg_val;
  assign io_out_bits_mdu_ctrl = io_in_bits_mdu_ctrl;
  assign io_out_bits_bit_ctrl = io_in_bits_bit_ctrl;
  assign io_out_bits_bit_data = isCrc8 ? _CRC8_EX1_io_bit_data : 32'h0;
  assign io_out_bits_bit_aux = isCrc8 ? _CRC8_EX1_io_bit_aux : 32'h0;
  assign io_out_bits_L_sign = io_in_bits_L_sign;
  assign io_out_bits_mem_bytes = io_in_bits_mem_bytes;
  assign io_out_bits_rd_addr = io_in_bits_rd_addr;
  assign io_out_bits_rd_wen = io_in_bits_rd_wen;
  assign io_out_bits_is_load = io_in_bits_mem_bytes != 2'h3 & ~io_in_bits_mem_wen;
  assign io_out_bits_envir = io_in_bits_envir;
  assign io_out_bits_when = io_in_bits_when;
  assign io_bpu_update_en =
    (io_in_bits_bru_ctrl[2:0] == 3'h1 | io_in_bits_jump) & exu_fire;
  assign io_bpu_update_pc = io_in_bits_pc;
  assign io_bpu_update_ras_push = io_in_bits_ras_push & exu_fire;
  assign io_bpu_update_ras_pop = io_in_bits_ras_pop & exu_fire;
  assign io_bpu_update_ras_addr = io_in_bits_snpc;
  assign io_branch_resolve_actual_pc = actual_pc;
  assign io_branch_resolve_actual_taken = _BRU_io_redirect | trap_redirect;
  assign io_branch_resolve_mispredict =
    _BRU_io_redirect
      ? _BRU_io_target_pc != io_in_bits_predicted_pc
      : trap_redirect
          ? trap_target_pc != io_in_bits_predicted_pc
          : io_in_bits_snpc != io_in_bits_predicted_pc;
  assign io_reg_val = reg_val;
  assign io_rd_wen = io_in_bits_rd_wen;
  assign io_rd_addr = io_in_bits_rd_addr;
  assign io_rd_when = io_in_bits_when;
endmodule

module CRC8Ex2(
  input  [31:0] io_bit_data,
                io_bit_aux,
  output [31:0] io_result
);

  wire        crc_x16 = io_bit_data[4] ^ io_bit_aux[0];
  wire [14:0] crc_cx = {1'h0, {14{crc_x16}} & 14'h2001} ^ io_bit_aux[15:1];
  wire        crc_x16_1 = io_bit_data[5] ^ crc_cx[0];
  wire [14:0] crc_cx_1 = {1'h0, {14{crc_x16_1}} & 14'h2001} ^ {crc_x16, crc_cx[14:1]};
  wire        crc_x16_2 = io_bit_data[6] ^ crc_cx_1[0];
  wire [14:0] crc_cx_2 = {1'h0, {14{crc_x16_2}} & 14'h2001} ^ {crc_x16_1, crc_cx_1[14:1]};
  wire        crc_x16_3 = io_bit_data[7] ^ crc_cx_2[0];
  assign io_result =
    {16'h0, crc_x16_3, {1'h0, {14{crc_x16_3}} & 14'h2001} ^ {crc_x16_2, crc_cx_2[14:1]}};
endmodule

module exu_ex2(
  output        io_in_ready,
  input         io_in_valid,
  input  [31:0] io_in_bits_pc,
                io_in_bits_pc_next,
                io_in_bits_reg_data,
  input  [4:0]  io_in_bits_mdu_ctrl,
  input  [3:0]  io_in_bits_bit_ctrl,
  input  [31:0] io_in_bits_bit_data,
                io_in_bits_bit_aux,
  input  [4:0]  io_in_bits_rd_addr,
  input         io_in_bits_rd_wen,
                io_in_bits_is_load,
  input  [2:0]  io_in_bits_envir,
  input  [4:0]  io_in_bits_when,
  input         io_out_ready,
  output        io_out_valid,
  output [31:0] io_out_bits_pc,
                io_out_bits_pc_next,
                io_out_bits_reg_data,
  output [4:0]  io_out_bits_mdu_ctrl,
  output [3:0]  io_out_bits_bit_ctrl,
  output [4:0]  io_out_bits_rd_addr,
  output        io_out_bits_rd_wen,
                io_out_bits_is_load,
                io_out_bits_cache_hit,
  output [2:0]  io_out_bits_envir,
  output [4:0]  io_out_bits_when,
  input         io_cache_hit,
  input  [31:0] io_rdata_fast,
  output [31:0] io_reg_val,
  output        io_rd_wen,
  output [4:0]  io_rd_addr,
                io_rd_when
);

  wire [31:0] _CRC8_EX2_io_result;
  wire        isCrc8 = io_in_bits_bit_ctrl == 4'h9;
  wire [31:0] reg_data =
    io_in_bits_bit_ctrl == 4'h1 | io_in_bits_bit_ctrl == 4'h2
    | io_in_bits_bit_ctrl == 4'h3 | io_in_bits_bit_ctrl == 4'h5
    | io_in_bits_bit_ctrl == 4'h6 | isCrc8
      ? (isCrc8 ? _CRC8_EX2_io_result : 32'h0)
      : io_in_bits_is_load & io_cache_hit ? io_rdata_fast : io_in_bits_reg_data;
  wire [4:0]  _io_rd_when_T = {3'h0, ~io_cache_hit, 1'h1};
  CRC8Ex2 CRC8_EX2 (
    .io_bit_data (io_in_bits_bit_data),
    .io_bit_aux  (io_in_bits_bit_aux),
    .io_result   (_CRC8_EX2_io_result)
  );
  assign io_in_ready = io_out_ready;
  assign io_out_valid = io_in_valid;
  assign io_out_bits_pc = io_in_bits_pc;
  assign io_out_bits_pc_next = io_in_bits_pc_next;
  assign io_out_bits_reg_data = reg_data;
  assign io_out_bits_mdu_ctrl = io_in_bits_mdu_ctrl;
  assign io_out_bits_bit_ctrl = io_in_bits_bit_ctrl;
  assign io_out_bits_rd_addr = io_in_bits_rd_addr;
  assign io_out_bits_rd_wen = io_in_bits_rd_wen;
  assign io_out_bits_is_load = io_in_bits_is_load;
  assign io_out_bits_cache_hit = io_cache_hit;
  assign io_out_bits_envir = io_in_bits_envir;
  assign io_out_bits_when = io_in_bits_is_load ? _io_rd_when_T : io_in_bits_when;
  assign io_reg_val = reg_data;
  assign io_rd_wen = io_in_bits_rd_wen;
  assign io_rd_addr = io_in_bits_rd_addr;
  assign io_rd_when = io_in_bits_is_load ? _io_rd_when_T : io_in_bits_when;
endmodule

module exu_ex3(
  output        io_in_ready,
  input         io_in_valid,
  input  [31:0] io_in_bits_pc,
                io_in_bits_pc_next,
                io_in_bits_reg_data,
  input  [4:0]  io_in_bits_mdu_ctrl,
  input  [3:0]  io_in_bits_bit_ctrl,
  input  [4:0]  io_in_bits_rd_addr,
  input         io_in_bits_rd_wen,
                io_in_bits_is_load,
                io_in_bits_cache_hit,
  input  [2:0]  io_in_bits_envir,
  input  [4:0]  io_in_bits_when,
  input         io_out_ready,
  output        io_out_valid,
  output [31:0] io_out_bits_pc,
                io_out_bits_pc_next,
  output        io_out_bits_rd_wen,
  output [4:0]  io_out_bits_rd_addr,
  output [31:0] io_out_bits_rd_data,
  output [4:0]  io_out_bits_mdu_ctrl,
  output [3:0]  io_out_bits_bit_ctrl,
  output [2:0]  io_out_bits_envir,
