module WBU(
  output        io_valid,
  input         io_in_valid,
  input  [31:0] io_in_bits_pc,
                io_in_bits_pc_next,
  input  [4:0]  io_in_bits_when,
                io_in_bits_mdu_ctrl,
  input  [3:0]  io_in_bits_bit_ctrl,
  input         io_in_bits_rd_wen,
  input  [4:0]  io_in_bits_rd_addr,
  input  [31:0] io_in_bits_rd_data,
  input  [2:0]  io_in_bits_envir,
  output [31:0] io_ex4_reg_val_q,
  input  [63:0] io_mul_out,
  input  [31:0] io_div_out,
  input         io_div_done,
                io_backend_stall,
  output        io_long_stall,
                io_gpr_wen,
  output [4:0]  io_gpr_addr,
  output [31:0] io_gpr_data,
  output        io_rd_wen,
  output [4:0]  io_rd_when,
  output        io_retire_valid,
  output [31:0] io_retire_pc,
                io_retire_pc_next,
  output        io_retire_rd_wen,
  output [4:0]  io_retire_rd,
  output [31:0] io_retire_wdata,
  output        io_retire_is_ebreak
);

  wire        _long_stall_T = io_in_bits_mdu_ctrl[1:0] == 2'h2;
  wire        is_clmul = io_in_bits_bit_ctrl == 4'h7;
  wire [31:0] reg_data =
    is_clmul
      ? 32'h0
      : _long_stall_T
          ? io_div_out
          : io_in_bits_mdu_ctrl[1:0] == 2'h1
              ? (io_in_bits_mdu_ctrl[2] ? io_mul_out[63:32] : io_mul_out[31:0])
              : io_in_bits_rd_data;
  wire        long_stall = io_in_valid & (_long_stall_T & ~io_div_done | is_clmul);
  wire        io_valid_0 = io_in_valid & ~long_stall & ~io_backend_stall;
  assign io_valid = io_valid_0;
  assign io_ex4_reg_val_q = io_in_bits_rd_data;
  assign io_long_stall = long_stall;
  assign io_gpr_wen = io_in_bits_rd_wen;
  assign io_gpr_addr = io_in_bits_rd_addr;
  assign io_gpr_data = reg_data;
  assign io_rd_wen = io_in_bits_rd_wen;
  assign io_rd_when = io_in_bits_when;
  assign io_retire_valid = io_valid_0;
  assign io_retire_pc = io_in_bits_pc;
  assign io_retire_pc_next = io_in_bits_pc_next;
  assign io_retire_rd_wen = io_in_bits_rd_wen;
  assign io_retire_rd = io_in_bits_rd_addr;
  assign io_retire_wdata = reg_data;
  assign io_retire_is_ebreak = io_in_bits_envir == 3'h2;
endmodule

module HZU(
  input         clock,
                reset,
                io_ex1_valid,
                io_ex1_bpu_update_en,
  input  [31:0] io_ex1_bpu_update_pc,
  input         io_ex1_bpu_update_ras_push,
                io_ex1_bpu_update_ras_pop,
  input  [31:0] io_ex1_bpu_update_ras_addr,
                io_ex1_branch_resolve_actual_pc,
  input         io_ex1_branch_resolve_actual_taken,
                io_ex1_branch_resolve_mispredict,
  output        io_hzu_bpu_update_en,
  output [31:0] io_hzu_bpu_update_pc,
  output        io_hzu_bpu_update_ras_push,
                io_hzu_bpu_update_ras_pop,
  output [31:0] io_hzu_bpu_update_ras_addr,
                io_hzu_branch_resolve_actual_pc,
  output        io_hzu_branch_resolve_actual_taken,
                io_hzu_hazard
);

  reg        hzu_bpu_update_en;
  reg [31:0] hzu_bpu_update_pc;
  reg [31:0] hzu_branch_resolve_actual_pc;
  reg        hzu_branch_resolve_actual_taken;
  reg        io_hzu_bpu_update_ras_push_REG;
  reg        io_hzu_bpu_update_ras_pop_REG;
  reg [31:0] io_hzu_bpu_update_ras_addr_REG;
  reg        io_hzu_hazard_REG;
  always @(posedge clock) begin
    hzu_bpu_update_en <= io_ex1_bpu_update_en;
    hzu_bpu_update_pc <= io_ex1_bpu_update_pc;
    hzu_branch_resolve_actual_pc <= io_ex1_branch_resolve_actual_pc;
    hzu_branch_resolve_actual_taken <= io_ex1_branch_resolve_actual_taken;
    io_hzu_bpu_update_ras_addr_REG <= io_ex1_bpu_update_ras_addr;
    io_hzu_hazard_REG <= io_ex1_branch_resolve_mispredict & io_ex1_valid;
    if (reset) begin
      io_hzu_bpu_update_ras_push_REG <= 1'h0;
      io_hzu_bpu_update_ras_pop_REG <= 1'h0;
    end
    else begin
      io_hzu_bpu_update_ras_push_REG <= io_ex1_bpu_update_ras_push;
      io_hzu_bpu_update_ras_pop_REG <= io_ex1_bpu_update_ras_pop;
    end
  end // always @(posedge)
  assign io_hzu_bpu_update_en = hzu_bpu_update_en;
  assign io_hzu_bpu_update_pc = hzu_bpu_update_pc;
  assign io_hzu_bpu_update_ras_push = io_hzu_bpu_update_ras_push_REG;
  assign io_hzu_bpu_update_ras_pop = io_hzu_bpu_update_ras_pop_REG;
  assign io_hzu_bpu_update_ras_addr = io_hzu_bpu_update_ras_addr_REG;
  assign io_hzu_branch_resolve_actual_pc = hzu_branch_resolve_actual_pc;
  assign io_hzu_branch_resolve_actual_taken = hzu_branch_resolve_actual_taken;
  assign io_hzu_hazard = io_hzu_hazard_REG;
endmodule

